  font-size: var(--font-size-xs);
}
.orders01-totals dt {
  color: var(--text-secondary);
}
.orders01-total {
  border-block-start: var(--border-width-thin) solid var(--border-default);
  margin-block-start: var(--space-2);
  font-weight: var(--font-weight-semibold);
}
.orders01-payment-note {
  text-align: end;
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  margin-block-start: var(--space-2);
}
.orders01-delivery {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  font-size: var(--font-size-xs);
}
.orders01-delivery strong {
  display: block;
  font-weight: var(--font-weight-medium);
  margin-block-end: var(--space-2);
}
.orders01-delivery a {
  color: var(--text-primary);
  text-underline-offset: var(--space-1);
}
.orders01-delivery address {
  font-style: normal;
  color: var(--text-secondary);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-2);
}
.orders01-delivery address span {
  display: block;
}
.orders01-tracking {
  margin-block-start: var(--space-3);
  color: var(--text-secondary);
  font-family: var(--font-family-mono);
}
.orders01-timeline {
  list-style: none;
  padding: 0;
}
.orders01-timeline li {
  position: relative;
  padding-inline-start: var(--space-5);
  padding-block-end: var(--space-5);
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.orders01-timeline li:last-child {
  padding-block-end: 0;
  border-color: transparent;
}
.orders01-timeline li::before {
  content: "";
  position: absolute;
  inset-inline-start: calc(var(--space-1) * -1);
  top: var(--space-1);
  width: var(--space-2);
  height: var(--space-2);
  background: var(--border-strong);
  border-radius: var(--radius-full);
}
.orders01-timeline li:first-child::before {
  background: var(--brand-primary);
}
.orders01-timeline strong {
  display: block;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
}
.orders01-timeline time,
.orders01-timeline p {
  display: block;
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-1);
}
.orders01-muted {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
}
.orders01-state,
.orders01-detail-empty {
  padding: var(--card-padding-lg);
}
.orders01-state .text,
.orders01-detail-empty .text {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
  margin-block: var(--space-4);
}
.orders01 .orders01-detail-empty h2 {
  font-size: var(--font-size-2xl);
  margin-block-start: var(--space-4);
}
.orders01 .orders01-state h3 {
  font-size: var(--font-size-lg);
}
.orders01-sr {
  position: absolute;
  width: var(--border-width-thin);
  height: var(--border-width-thin);
  padding: 0;
  margin: calc(var(--border-width-thin) * -1);
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 1050px) {
  .orders01-workbench {
    flex-direction: column;
  }
  .orders01-list,
  .orders01-detail {
    width: 100%;
    flex-basis: auto;
  }
  .orders01-detail {
    position: static;
    order: 1;
  }
  .orders01-list {
    order: 0;
  }
  .orders01-delivery {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .orders01-delivery > div {
    flex: 1;
  }
}
@media (max-width: 640px) {
  .orders01 {
    padding: var(--container-padding);
  }
  .orders01-heading {
    flex-direction: column;
    align-items: start;
  }
  .orders01 .orders01-heading h1 {
    font-size: var(--font-size-3xl);
  }
  .orders01-metrics > div {
    flex-basis: 50%;
    padding: var(--space-4);
  }
  .orders01-metrics > div:nth-child(odd) {
    border-inline-start: 0;
    padding-inline-start: 0;
  }
  .orders01-metrics > div:nth-child(n + 3) {
    border-block-start: var(--border-width-thin) solid var(--border-default);
  }
  .orders01-list-heading {
    align-items: start;
    flex-direction: column;
  }
  .orders01-search,
  .orders01-sort {
    flex-basis: 100%;
  }
  .orders01-pagination {
    justify-content: center;
  }
}
